#!/usr/bin/env python3
"""Independent stdlib-only validator for a classic PCAP generated by PcapWriter."""
import struct
import sys
from pathlib import Path

p = Path(sys.argv[1])
data = p.read_bytes()
assert len(data) >= 24, "truncated global header"
magic, major, minor, thiszone, sigfigs, snaplen, network = struct.unpack_from("<IHHiiii", data, 0)
assert magic == 0xA1B2C3D4, f"unexpected PCAP magic: {magic:#x}"
assert (major, minor) == (2, 4), f"unexpected PCAP version {major}.{minor}"
assert snaplen == 65535, f"unexpected snaplen: {snaplen}"
assert network == 101, f"expected DLT_RAW=101, got {network}"
assert thiszone == 0 and sigfigs == 0
pos = 24
records = []
while pos < len(data):
    assert pos + 16 <= len(data), "truncated record header"
    sec, usec, captured, original = struct.unpack_from("<IIII", data, pos)
    pos += 16
    assert usec < 1_000_000, f"invalid microsecond fraction: {usec}"
    assert 0 < captured <= snaplen, f"invalid captured length: {captured}"
    assert original >= captured, f"original length {original} < captured {captured}"
    assert pos + captured <= len(data), "truncated packet bytes"
    packet = data[pos:pos + captured]
    pos += captured
    assert (packet[0] >> 4) in (4, 6), "DLT_RAW packet is not IPv4/IPv6"
    records.append((sec, usec, captured, original, packet[0] >> 4))
assert pos == len(data), "trailing bytes or bad record boundary"
assert len(records) == 2, f"expected two records, got {len(records)}"
assert records[0][0:4] == (1, 234000, 28, 28), records[0]
assert records[1][0:4] == (2, 345000, 48, 48), records[1]
assert [r[4] for r in records] == [4, 6], records
print("PASS: independent PCAP parser accepted global header and 2 IPv4/IPv6 records, timestamps and lengths")
